-- Native operational schema v1. Changes require a NEW migration, never edit after release.

CREATE TABLE "access_groups" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL UNIQUE,
  "description" TEXT NOT NULL DEFAULT '',
  "active" BIGINT NOT NULL DEFAULT 1,
  "version" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL
);

CREATE TABLE "account_plan_batches" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "filename" TEXT NOT NULL,
  "format" TEXT NOT NULL,
  "sha256" TEXT NOT NULL,
  "original" BYTEA NOT NULL,
  "options_json" TEXT NOT NULL,
  "plan_json" TEXT NOT NULL,
  "preview_hash" TEXT NOT NULL,
  "state_hash" TEXT NOT NULL,
  "status" TEXT NOT NULL CHECK ("status" IN ('preview', 'confirmed', 'reference')),
  "confirmation_json" TEXT,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "account_plan_metadata" (
  "company_id" BIGINT NOT NULL,
  "account_id" BIGINT NOT NULL,
  "prosoft_json" TEXT NOT NULL,
  "extras_json" TEXT NOT NULL DEFAULT '{}',
  "batch_id" BIGINT NOT NULL,
  PRIMARY KEY ("company_id", "account_id")
);

CREATE TABLE "account_plan_properties" (
  "company_id" BIGINT PRIMARY KEY,
  "properties_json" TEXT NOT NULL,
  "extras_json" TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE "accounts" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "access_code" TEXT NOT NULL,
  "classifier" TEXT,
  "name" TEXT,
  "nature" TEXT CHECK ("nature" IN ('debit', 'credit')),
  "analytical" BIGINT CHECK ("analytical" IN (0, 1)),
  "requires_cost_center" BIGINT CHECK ("requires_cost_center" IN (0, 1)),
  "active" BIGINT DEFAULT 1,
  "version" BIGINT NOT NULL DEFAULT 1,
  "shared_entry_id" BIGINT,
  "report_group" TEXT DEFAULT '',
  "prosoft_code" TEXT DEFAULT '',
  UNIQUE (
    "company_id",
    "access_code"
  ),
  UNIQUE (
    "company_id",
    "id"
  ),
  CONSTRAINT "account_definition_or_reference" CHECK (NOT "shared_entry_id" IS NULL
  OR (
    NOT "classifier" IS NULL
    AND NOT "name" IS NULL
    AND NOT "nature" IS NULL
    AND NOT "analytical" IS NULL
    AND NOT "requires_cost_center" IS NULL
    AND NOT "active" IS NULL
  ))
);

CREATE TABLE "audit" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT,
  "actor" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "entity" TEXT NOT NULL,
  "entity_id" TEXT NOT NULL,
  "details_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL
);

CREATE TABLE "auditor_attachments" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "job_id" BIGINT NOT NULL,
  "document_ref" TEXT NOT NULL,
  "file_id" BIGINT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "job_id",
    "document_ref",
    "file_id"
  )
);

CREATE TABLE "auditor_auxiliary" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "job_id" BIGINT NOT NULL,
  "document_ref" TEXT NOT NULL,
  "file_id" BIGINT NOT NULL,
  "renderer" TEXT NOT NULL,
  "source_sha256" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "job_id",
    "document_ref"
  )
);

CREATE TABLE "auditor_catalog_sources" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "file_id" BIGINT NOT NULL,
  "preview_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "auditor_catalogs" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "name" TEXT NOT NULL,
  "version" BIGINT NOT NULL DEFAULT 1,
  "state" TEXT NOT NULL DEFAULT 'draft',
  "source" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_to" TEXT NOT NULL,
  "content_json" TEXT NOT NULL,
  "sha256" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  "published_at" TEXT,
  "published_by" TEXT,
  "review_reason" TEXT,
  "source_id" BIGINT,
  "reference_json" TEXT NOT NULL DEFAULT '{}',
  "parent_id" BIGINT,
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "auditor_findings" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "job_id" BIGINT NOT NULL,
  "payload_json" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'open',
  "responsible" TEXT NOT NULL DEFAULT '',
  "treatment" TEXT NOT NULL DEFAULT '',
  "version" BIGINT NOT NULL DEFAULT 1,
  "updated_at" TEXT,
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "auditor_jobs" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "year" BIGINT NOT NULL,
  "mode" TEXT NOT NULL,
  "start" TEXT NOT NULL,
  "end" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'queued',
  "version" BIGINT NOT NULL DEFAULT 1,
  "request_key" TEXT NOT NULL,
  "request_hash" TEXT NOT NULL,
  "snapshot_json" TEXT NOT NULL,
  "result_json" TEXT,
  "error" TEXT,
  "cancelled" BIGINT NOT NULL DEFAULT 0,
  "deleted_at" TEXT,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  "user_id" BIGINT,
  "finished_at" TEXT,
  "name" TEXT NOT NULL DEFAULT '',
  "stage" TEXT NOT NULL DEFAULT 'queued',
  "progress" BIGINT NOT NULL DEFAULT 0,
  "processed_files" BIGINT NOT NULL DEFAULT 0,
  "total_files" BIGINT NOT NULL DEFAULT 0,
  "parent_id" BIGINT,
  "started_at" TEXT,
  UNIQUE (
    "company_id",
    "request_key"
  ),
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "auditor_logs" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "job_id" BIGINT NOT NULL,
  "level" TEXT NOT NULL,
  "message" TEXT NOT NULL,
  "created_at" TEXT NOT NULL
);

CREATE TABLE "auditor_reports" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "job_id" BIGINT NOT NULL,
  "format" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  "file_id" BIGINT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "job_id",
    "format",
    "revision"
  )
);

CREATE TABLE "bank_allocations" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "transaction_id" BIGINT NOT NULL,
  "title_id" BIGINT NOT NULL,
  "amount_cents" BIGINT NOT NULL CHECK ("amount_cents" > 0),
  "settlement_id" BIGINT,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  "reversed_at" TEXT
);

CREATE TABLE "bank_transactions" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "bank_account" TEXT NOT NULL,
  "date" TEXT NOT NULL,
  "amount_cents" BIGINT NOT NULL CHECK ("amount_cents" <> 0),
  "description" TEXT NOT NULL,
  "reference" TEXT NOT NULL,
  "external_id" TEXT NOT NULL,
  "source_json" TEXT NOT NULL,
  "source_hash" TEXT NOT NULL,
  "fingerprint" TEXT NOT NULL,
  "payload_hash" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "bank_account",
    "fingerprint"
  ),
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "bulk_deleted_movements" (
  "kind" TEXT NOT NULL,
  "record_id" BIGINT NOT NULL,
  "company_id" BIGINT NOT NULL,
  "idempotency_key" TEXT,
  "deleted_at" TEXT NOT NULL,
  PRIMARY KEY ("kind", "record_id")
);

CREATE TABLE "bulk_previews" (
  "id" TEXT PRIMARY KEY,
  "company_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "token_hash" TEXT NOT NULL DEFAULT '',
  "request_json" TEXT NOT NULL,
  "preview_hash" TEXT NOT NULL,
  "expires_at" DOUBLE PRECISION NOT NULL,
  "result_json" TEXT,
  "confirmation_hash" TEXT,
  "created_at" DOUBLE PRECISION NOT NULL
);

CREATE TABLE "calculations" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "rule_id" BIGINT NOT NULL,
  "payload_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL
);

CREATE TABLE "catalogs" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "kind" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "direction" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_to" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "active" BIGINT NOT NULL DEFAULT 1,
  "version" BIGINT NOT NULL DEFAULT 1,
  UNIQUE (
    "company_id",
    "kind",
    "code",
    "direction"
  )
);

CREATE TABLE "companies" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "code" TEXT NOT NULL UNIQUE,
  "name" TEXT NOT NULL,
  "trade_name" TEXT NOT NULL DEFAULT '',
  "tax_id" TEXT NOT NULL UNIQUE,
  "regime" TEXT NOT NULL,
  "state" TEXT NOT NULL DEFAULT '',
  "city" TEXT NOT NULL DEFAULT '',
  "address" TEXT NOT NULL DEFAULT '',
  "number" TEXT NOT NULL DEFAULT '',
  "district" TEXT NOT NULL DEFAULT '',
  "postal_code" TEXT NOT NULL DEFAULT '',
  "ibge" TEXT NOT NULL DEFAULT '',
  "ie" TEXT NOT NULL DEFAULT '',
  "im" TEXT NOT NULL DEFAULT '',
  "cnae" TEXT NOT NULL DEFAULT '',
  "email" TEXT NOT NULL DEFAULT '',
  "phone" TEXT NOT NULL DEFAULT '',
  "prosoft_code" TEXT NOT NULL DEFAULT '',
  "version" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  "profile_json" TEXT NOT NULL DEFAULT '{}'
);

CREATE TABLE "company_account_aliases" (
  "company_id" BIGINT NOT NULL,
  "global_entry_id" BIGINT NOT NULL,
  "account_id" BIGINT NOT NULL,
  "used" BIGINT NOT NULL DEFAULT 1 CHECK ("used" IN (0, 1)),
  PRIMARY KEY ("company_id", "global_entry_id")
);

CREATE TABLE "company_account_plan_bindings" (
  "company_id" BIGINT PRIMARY KEY,
  "global_plan_id" BIGINT NOT NULL,
  "mode" TEXT NOT NULL CHECK ("mode" IN ('shared', 'own')),
  "version" BIGINT NOT NULL DEFAULT 1,
  "attached_at" TEXT NOT NULL,
  "attached_by" TEXT NOT NULL,
  "copy_scope" TEXT NOT NULL DEFAULT 'all' CHECK ("copy_scope" IN ('all', 'used'))
);

CREATE TABLE "company_fiscal_pattern_imports" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "pattern_id" BIGINT NOT NULL,
  "pattern_version" BIGINT NOT NULL,
  "fingerprint" TEXT NOT NULL,
  "snapshot_json" TEXT NOT NULL,
  "rule_ids_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "fingerprint"
  )
);

CREATE TABLE "company_operational_settings" (
  "company_id" BIGINT PRIMARY KEY,
  "settings_json" TEXT NOT NULL,
  "version" BIGINT NOT NULL DEFAULT 1,
  "updated_at" TEXT NOT NULL,
  "updated_by" TEXT NOT NULL
);

CREATE TABLE "cost_centers" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "active" BIGINT NOT NULL DEFAULT 1,
  "version" BIGINT NOT NULL DEFAULT 1,
  "prosoft_code" TEXT NOT NULL DEFAULT '',
  UNIQUE (
    "company_id",
    "code"
  ),
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "document_sources" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "document_id" BIGINT NOT NULL,
  "source_hash" TEXT NOT NULL,
  "source_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  UNIQUE (
    "document_id",
    "source_hash",
    "source_json"
  )
);

CREATE TABLE "documents" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "direction" TEXT NOT NULL CHECK ("direction" IN ('incoming', 'outgoing')),
  "number" TEXT NOT NULL,
  "series" TEXT NOT NULL,
  "model" TEXT NOT NULL,
  "issue_date" TEXT NOT NULL,
  "posting_date" TEXT NOT NULL,
  "period" TEXT NOT NULL,
  "partner_name" TEXT NOT NULL,
  "partner_tax_id" TEXT NOT NULL,
  "key" TEXT NOT NULL,
  "cfop" TEXT NOT NULL,
  "total_cents" BIGINT NOT NULL CHECK ("total_cents" >= 0),
  "taxes_json" TEXT NOT NULL,
  "items_json" TEXT NOT NULL,
  "source_json" TEXT NOT NULL,
  "extra_json" TEXT NOT NULL DEFAULT '{}',
  "source_hash" TEXT NOT NULL,
  "business_key" TEXT NOT NULL,
  "payload_hash" TEXT NOT NULL,
  "status" TEXT NOT NULL CHECK ("status" IN ('pending', 'reviewed', 'booked')),
  "version" BIGINT NOT NULL DEFAULT 1,
  "journal_id" BIGINT,
  "reviewed_by" TEXT,
  "review_reason" TEXT,
  "booked_by" TEXT,
  "book_reason" TEXT,
  "created_at" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "business_key"
  ),
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "exercises" (
  "company_id" BIGINT NOT NULL,
  "module" TEXT NOT NULL,
  "year" BIGINT NOT NULL CHECK ("year" BETWEEN 1900 AND 2199),
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  PRIMARY KEY ("company_id", "module", "year")
);

CREATE TABLE "export_batches" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "period" TEXT NOT NULL,
  "layout" TEXT NOT NULL,
  "fingerprint" TEXT NOT NULL,
  "filename" TEXT NOT NULL,
  "content" BYTEA NOT NULL,
  "manifest_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "layout",
    "fingerprint"
  )
);

CREATE TABLE "fiscal_library_versions" (
  "entity_type" TEXT NOT NULL,
  "entity_id" BIGINT NOT NULL,
  "version" BIGINT NOT NULL,
  "data_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  PRIMARY KEY ("entity_type", "entity_id", "version")
);

CREATE TABLE "fiscal_patterns" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "code" TEXT NOT NULL UNIQUE,
  "data_json" TEXT NOT NULL,
  "active" BIGINT NOT NULL DEFAULT 1,
  "version" BIGINT NOT NULL DEFAULT 1,
  "updated_at" TEXT NOT NULL
);

CREATE TABLE "global_account_entries" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "global_plan_id" BIGINT NOT NULL,
  "access_code" TEXT NOT NULL,
  "classifier" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "nature" TEXT NOT NULL CHECK ("nature" IN ('debit', 'credit')),
  "analytical" BIGINT NOT NULL CHECK ("analytical" IN (0, 1)),
  "requires_cost_center" BIGINT NOT NULL CHECK ("requires_cost_center" IN (0, 1)),
  "active" BIGINT NOT NULL,
  "report_group" TEXT NOT NULL,
  "prosoft_code" TEXT NOT NULL,
  "prosoft_json" TEXT NOT NULL,
  "extras_json" TEXT NOT NULL,
  UNIQUE (
    "global_plan_id",
    "access_code"
  )
);

CREATE TABLE "global_account_plan_links" (
  "company_id" BIGINT NOT NULL,
  "account_id" BIGINT NOT NULL,
  "global_plan_id" BIGINT NOT NULL,
  "access_code" TEXT NOT NULL,
  PRIMARY KEY ("company_id", "account_id")
);

CREATE TABLE "global_account_plan_previews" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "global_plan_id" BIGINT NOT NULL,
  "mode" TEXT NOT NULL,
  "state_hash" TEXT NOT NULL,
  "preview_hash" TEXT NOT NULL,
  "result_json" TEXT,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  "copy_scope" TEXT NOT NULL DEFAULT 'all' CHECK ("copy_scope" IN ('all', 'used'))
);

CREATE TABLE "global_account_plans" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "source_company_id" BIGINT NOT NULL,
  "source_batch_id" BIGINT NOT NULL,
  "parent_id" BIGINT,
  "plan_json" TEXT NOT NULL,
  "filename" TEXT NOT NULL,
  "format" TEXT NOT NULL,
  "original" BYTEA NOT NULL,
  "sha256" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL
);

CREATE TABLE "global_fiscal_catalogs" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "kind" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "namespace" TEXT NOT NULL DEFAULT '',
  "data_json" TEXT NOT NULL,
  "active" BIGINT NOT NULL DEFAULT 1,
  "version" BIGINT NOT NULL DEFAULT 1,
  "updated_at" TEXT NOT NULL,
  UNIQUE (
    "kind",
    "namespace",
    "code"
  )
);

CREATE TABLE "global_fiscal_sources" (
  "bundle_id" TEXT PRIMARY KEY,
  "data_json" TEXT NOT NULL,
  "sha256" TEXT NOT NULL
);

CREATE TABLE "group_companies" (
  "group_id" BIGINT NOT NULL,
  "company_id" BIGINT NOT NULL,
  PRIMARY KEY ("group_id", "company_id")
);

CREATE TABLE "group_permissions" (
  "group_id" BIGINT NOT NULL,
  "company_id" BIGINT NOT NULL,
  "routine" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "effect" TEXT NOT NULL CHECK ("effect" IN ('allow', 'deny')),
  PRIMARY KEY ("group_id", "company_id", "routine", "action")
);

CREATE TABLE "group_users" (
  "group_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  PRIMARY KEY ("group_id", "user_id")
);

CREATE TABLE "import_package_history" (
  "import_id" BIGINT PRIMARY KEY,
  "company_id" BIGINT NOT NULL,
  "hidden_at" TEXT NOT NULL,
  "hidden_by" TEXT NOT NULL
);

CREATE TABLE "import_package_settings" (
  "company_id" BIGINT PRIMARY KEY,
  "payload_json" TEXT NOT NULL,
  "configured_by" BIGINT,
  "last_run" TEXT
);

CREATE TABLE "import_package_tombstones" (
  "import_id" BIGINT PRIMARY KEY,
  "company_id" BIGINT NOT NULL,
  "removed_at" TEXT NOT NULL,
  "removed_by" TEXT NOT NULL,
  "original_bytes" BIGINT NOT NULL,
  "history_hidden" BIGINT NOT NULL DEFAULT 0,
  "sha256" TEXT NOT NULL
);

CREATE TABLE "imports" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "filename" TEXT NOT NULL,
  "sha256" TEXT NOT NULL,
  "identity_hash" TEXT NOT NULL,
  "preview_hash" TEXT NOT NULL,
  "period" TEXT NOT NULL,
  "company_tax_id" TEXT NOT NULL,
  "options_json" TEXT NOT NULL,
  "original" BYTEA NOT NULL,
  "parsed_json" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "bank_account" TEXT NOT NULL,
  "confirmation_json" TEXT,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "identity_hash"
  ),
  UNIQUE (
    "company_id",
    "id"
  )
);

CREATE TABLE "integration_credentials" (
  "id" TEXT PRIMARY KEY,
  "company_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "token_hash" TEXT NOT NULL UNIQUE,
  "scopes" TEXT NOT NULL,
  "expires" DOUBLE PRECISION NOT NULL,
  "revoked" BIGINT NOT NULL DEFAULT 0,
  "created" DOUBLE PRECISION NOT NULL
);

CREATE TABLE "integration_deliveries" (
  "webhook_id" TEXT NOT NULL,
  "event_seq" BIGINT NOT NULL,
  "attempts" BIGINT NOT NULL DEFAULT 0,
  "next_at" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "state" TEXT NOT NULL DEFAULT 'pending',
  "last_result" TEXT,
  PRIMARY KEY ("webhook_id", "event_seq")
);

CREATE TABLE "integration_events" (
  "seq" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "id" TEXT NOT NULL UNIQUE,
  "company_id" BIGINT NOT NULL,
  "resource_id" TEXT NOT NULL,
  "version" BIGINT NOT NULL,
  "operation" TEXT NOT NULL,
  "created" TEXT NOT NULL,
  "resource" TEXT NOT NULL DEFAULT 'cost-centers'
);

CREATE TABLE "integration_limits" (
  "credential_id" TEXT PRIMARY KEY,
  "window" BIGINT NOT NULL,
  "requests" BIGINT NOT NULL
);

CREATE TABLE "integration_redrives" (
  "webhook_id" TEXT NOT NULL,
  "event_seq" BIGINT NOT NULL,
  "key" TEXT NOT NULL,
  "request_hash" TEXT NOT NULL,
  "created" DOUBLE PRECISION NOT NULL,
  PRIMARY KEY ("webhook_id", "event_seq", "key")
);

CREATE TABLE "integration_webhooks" (
  "id" TEXT PRIMARY KEY,
  "credential_id" TEXT NOT NULL,
  "url" TEXT NOT NULL,
  "start_seq" BIGINT NOT NULL,
  "revoked" BIGINT NOT NULL DEFAULT 0,
  "resource" TEXT NOT NULL DEFAULT 'cost-centers'
);

CREATE TABLE "journal_lines" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "journal_id" BIGINT NOT NULL,
  "position" BIGINT NOT NULL,
  "account_id" BIGINT NOT NULL,
  "debit_cents" BIGINT NOT NULL CHECK ("debit_cents" >= 0),
  "credit_cents" BIGINT NOT NULL CHECK ("credit_cents" >= 0),
  "cost_center_id" BIGINT,
  "participant_id" BIGINT,
  CHECK ((
    "debit_cents" > 0 AND "credit_cents" = 0
  )
  OR (
    "credit_cents" > 0 AND "debit_cents" = 0
  )),
  UNIQUE (
    "journal_id",
    "position"
  )
);

CREATE TABLE "journals" (
  "id" BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "company_id" BIGINT NOT NULL,
  "number" BIGINT NOT NULL,
  "date" TEXT NOT NULL,
  "period" TEXT NOT NULL,
  "document" TEXT NOT NULL,
  "history" TEXT NOT NULL,
  "total_cents" BIGINT NOT NULL CHECK ("total_cents" > 0),
  "idempotency_key" TEXT NOT NULL,
  "request_hash" TEXT NOT NULL,
  "reversal_of" BIGINT,
  "reversed_by" BIGINT,
  "created_at" TEXT NOT NULL,
  "created_by" TEXT NOT NULL,
  UNIQUE (
    "company_id",
    "number"
  ),
  UNIQUE (
    "company_id",
    "idempotency_key"
  ),
  UNIQUE (
    "company_id",
    "id"
  ),
  UNIQUE (
    "reversal_of"
  )
);

CREATE TABLE "login_attempts" (
  "attempt_key" TEXT PRIMARY KEY,
  "failures" BIGINT NOT NULL,
  "locked_until" DOUBLE PRECISION NOT NULL
);

CREATE TABLE "lookup_cache" (
  "kind" TEXT NOT NULL,
  "query" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "data_json" TEXT NOT NULL,
  "fetched_at" TEXT NOT NULL,
  "expires_at" DOUBLE PRECISION NOT NULL,
  PRIMARY KEY ("kind", "query", "provider")
);

CREATE TABLE "lookup_limits" (
  "provider" TEXT PRIMARY KEY,
  "window_start" DOUBLE PRECISION NOT NULL,
  "count" BIGINT NOT NULL,
