CREATE VIEW "effective_accounts" AS
SELECT
  "a"."id",
  "a"."company_id",
  "a"."access_code",
  COALESCE("a"."classifier", "g"."classifier") AS "classifier",
  COALESCE("a"."name", "g"."name") AS "name",
  COALESCE("a"."nature", "g"."nature") AS "nature",
  COALESCE("a"."analytical", "g"."analytical") AS "analytical",
  COALESCE("a"."requires_cost_center", "g"."requires_cost_center") AS "requires_cost_center",
  COALESCE("a"."active", "g"."active") AS "active",
  "a"."version",
  COALESCE("a"."report_group", "g"."report_group") AS "report_group",
  COALESCE("a"."prosoft_code", "g"."prosoft_code") AS "prosoft_code",
  "a"."shared_entry_id"
FROM "accounts" AS "a"
LEFT JOIN "global_account_entries" AS "g"
  ON "g"."id" = "a"."shared_entry_id"
UNION ALL
SELECT
  -"g"."id",
  "b"."company_id",
  "g"."access_code",
  "g"."classifier",
  "g"."name",
  "g"."nature",
  "g"."analytical",
  "g"."requires_cost_center",
  "g"."active",
  1,
  "g"."report_group",
  "g"."prosoft_code",
  "g"."id"
FROM "company_account_plan_bindings" AS "b"
JOIN "global_account_entries" AS "g"
  ON "g"."global_plan_id" = "b"."global_plan_id"
WHERE
  "b"."mode" = 'shared'
  AND NOT EXISTS(
    SELECT
      1
    FROM "accounts" AS "a"
    WHERE
      "a"."company_id" = "b"."company_id" AND "a"."access_code" = "g"."access_code"
  );

CREATE UNIQUE INDEX "users_username_nocase" ON "users" (lower("username" COLLATE "C"));

CREATE UNIQUE INDEX "companies_code_nocase" ON "companies" (lower("code" COLLATE "C"));

CREATE UNIQUE INDEX "access_groups_name_nocase" ON "access_groups" (lower("name" COLLATE "C"));

CREATE FUNCTION json_each(text) RETURNS TABLE(value bigint) LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT value::bigint FROM jsonb_array_elements_text($1::jsonb) $$;

CREATE FUNCTION julianday(text) RETURNS double precision LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT extract(epoch FROM $1::date)::double precision / 86400 + 2440587.5 $$;
